import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 单元 4 复习与自测 · 第81–89课","description":"L73–L96 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 4 复习与自测 · 第81–89课","description":"L73–L96 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-04/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 4 复习与自测","summary":"L73–L96 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 4 复习与自测 · 第73–80课","link":"/life/english/new-concept/book-2/unit-04/review-part-01"},"next":{"text":"第二册：实践与进步 · 单元 4 复习与自测 · 第90–96课","link":"/life/english/new-concept/book-2/unit-04/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 4 复习与自测 · 第73–80课","link":"/life/english/new-concept/book-2/unit-04/review-part-01"},"next":{"text":"第二册：实践与进步 · 单元 4 复习与自测 · 第90–96课","link":"/life/english/new-concept/book-2/unit-04/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/review-part-02.md","filePath":"life/english/new-concept/book-2/unit-04/review-part-02.md"}'),n={name:"life/english/new-concept/book-2/unit-04/review-part-02.md"};function r(i,e,l,h,d,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-单元-4-复习与自测-·-第81–89课" tabindex="-1">第二册：实践与进步 · 单元 4 复习与自测 · 第81–89课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-4-复习与自测-·-第81–89课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 4 复习与自测 · 第81–89课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-04/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-81-·-分词修饰与逻辑主语" tabindex="-1">Lesson 81 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-81-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 81 · 分词修饰与逻辑主语 {#lesson-81-·-分词修饰与逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Dressed as a cleaner, the prisoner walked towards the side gate.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>分词 Dressed as a cleaner 修饰谁？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The prisoner.</p><p><strong>解析：</strong> 分词状语通常与主句主语一致。</p></details><p><strong>表达迁移：</strong> 写一段虚构推理场景，给出一个外表线索和一个克制的核查行动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Dressed as a cleaner, the prisoner walked towards the side gate. A guard noticed that his shoes did not match the uniform. The guard asked him to wait.</p><p>第一句的组织方式：Dressed 为过去分词状语，逻辑主语是 prisoner；walked 为主句谓语，towards 表方向。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Dressed as a cleaner, the gate opened 会使分词逻辑主语变成门，形成悬垂结构。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-081">回看本课</a></p><h2 id="lesson-82-·-情态动词的意义与形式" tabindex="-1">Lesson 82 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-82-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 82 · 情态动词的意义与形式 {#lesson-82-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The shape in the photograph might have been a large fish.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>补全：It might ___ been a fish.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 情态动词对过去推测用 have 加过去分词。</p></details><p><strong>表达迁移：</strong> 写一段模糊照片分析，给出一种可能解释和仍缺少的信息。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The shape in the photograph might have been a large fish. The photographer could not estimate its size. Researchers asked for the original image before commenting.</p><p>第一句的组织方式：might have been 为对过去身份的推测，a large fish 为表语；might 表不确定，不是过去能力。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：might was 不合结构；过去推测用 might have been。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-082">回看本课</a></p><h2 id="lesson-83-·-将来表达与安排" tabindex="-1">Lesson 83 · 将来表达与安排 <a class="header-anchor" href="#lesson-83-·-将来表达与安排" aria-label="Permalink to &quot;Lesson 83 · 将来表达与安排 {#lesson-83-·-将来表达与安排}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The candidate promised that the council would publish a plan by June.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>填 by/in：The deadline is June; the plan must appear ___ June.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> by</p><p><strong>解析：</strong> by 标记完成期限。</p></details><p><strong>表达迁移：</strong> 写三句公共承诺记录，包含承诺者、截止时间和未明确的问题。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The candidate promised that the council would publish a plan by June. Residents asked how the work would be funded. The candidate said the details were still being prepared.</p><p>第一句的组织方式：promised 明确信息来源，would publish 是过去视角的将来，by June 表截止时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：by June 与 in June 不同：前者指最迟到该时间，后者指在该月内。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-083">回看本课</a></p><h2 id="lesson-84-·-将来进行时与过程" tabindex="-1">Lesson 84 · 将来进行时与过程 <a class="header-anchor" href="#lesson-84-·-将来进行时与过程" aria-label="Permalink to &quot;Lesson 84 · 将来进行时与过程 {#lesson-84-·-将来进行时与过程}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> At ten tomorrow, the two sides will be discussing the revised offer.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>改正：They will discuss about the offer。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> They will discuss the offer.</p><p><strong>解析：</strong> discuss 是及物动词，无需 about。</p></details><p><strong>表达迁移：</strong> 写一段中立谈判进度说明，分清已完成的准备和仍未达成的结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>At ten tomorrow, the two sides will be discussing the revised offer. No agreement has been signed yet. Both groups have selected representatives for the meeting.</p><p>第一句的组织方式：will be discussing 为将来进行时，the two sides 是复数主语，revised 为过去分词定语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：discuss about the offer 多余 about；discuss 直接接宾语。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-084">回看本课</a></p><h2 id="lesson-85-·-不定式与目的" tabindex="-1">Lesson 85 · 不定式与目的 <a class="header-anchor" href="#lesson-85-·-不定式与目的" aria-label="Permalink to &quot;Lesson 85 · 不定式与目的 {#lesson-85-·-不定式与目的}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Ruth was nervous, but she was not too old to learn coding.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>选 old too/too old：She is not ___ to learn.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> too old</p><p><strong>解析：</strong> too 位于形容词前。</p></details><p><strong>表达迁移：</strong> 写一个成年学习者的起点、练习计划和可观察的小成果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Ruth was nervous, but she was not too old to learn coding. She practised for twenty minutes each evening. After a month, she wrote a simple program herself.</p><p>第一句的组织方式：not too old to learn 否定年龄成为绝对障碍；to learn 为结果相关不定式，coding 是 learn 的宾语内容。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：enough confident 语序错误，应为 confident enough；too old 与 very old 意义不同。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-085">回看本课</a></p><h2 id="lesson-86-·-分词修饰与逻辑主语" tabindex="-1">Lesson 86 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-86-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 86 · 分词修饰与逻辑主语 {#lesson-86-·-分词修饰与逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Hearing a strange sound, the driver slowed down immediately.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>句中 Hearing 的逻辑主语是谁？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The driver.</p><p><strong>解析：</strong> 分词状语与主句主语一致。</p></details><p><strong>表达迁移：</strong> 按顺序写一次设备异常：先兆、反应、最终处理，避免混淆行动者。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Hearing a strange sound, the driver slowed down immediately. The steering then became stiff. She stopped in a safe area and called for assistance.</p><p>第一句的组织方式：Hearing 的执行者是 driver；slowed down 为主句谓语，immediately 是时间方式相关副词。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Hearing a sound, the wheel broke 让 wheel 成听声者，不符合意思。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-086">回看本课</a></p><h2 id="lesson-87-·-间接引语与视角转换" tabindex="-1">Lesson 87 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-87-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 87 · 间接引语与视角转换 {#lesson-87-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The officer asked where Daniel had been before eight.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>选择：asked where he had been / asked where had he been.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> asked where he had been</p><p><strong>解析：</strong> 间接疑问使用陈述语序。</p></details><p><strong>表达迁移：</strong> 写三句调查记录：提出的问题、当事人回答和独立核对资料。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The officer asked where Daniel had been before eight. Daniel said he had visited his aunt. A shop receipt later placed him in another street.</p><p>第一句的组织方式：asked 引出间接特殊疑问，where 从句按主语 Daniel 加 had been 排列；before eight 是核对时段。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：He said ... 不等于 It was proved ...；陈述和证据必须分别标识。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-087">回看本课</a></p><h2 id="lesson-88-·-被动语态与信息重点" tabindex="-1">Lesson 88 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-88-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 88 · 被动语态与信息重点 {#lesson-88-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Fresh air will be supplied through a narrow pipe.</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>补全：Air will ___ supplied through the pipe.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> 将来被动使用 will be 加过去分词。</p></details><p><strong>表达迁移：</strong> 写一份虚构救援进度：已完成一项、正在做一项、还需达到的条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Fresh air will be supplied through a narrow pipe. Rescuers have reached the chamber with a radio cable. Drilling will continue until the opening is wide enough.</p><p>第一句的组织方式：will be supplied 是将来被动，through 引出通道，Fresh air 不可数。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：through a pipe 指穿过管道内部；across a pipe 则是横跨，不适合输送通道。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-088">回看本课</a></p><h2 id="lesson-89-·-动词、宾语与补足语" tabindex="-1">Lesson 89 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-89-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 89 · 动词、宾语与补足语 {#lesson-89-·-动词、宾语与补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I meant to say Thursday, but I accidentally said Tuesday.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>填 to say/saying：I meant ___ Thursday.（原本想说）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to say</p><p><strong>解析：</strong> mean to do 表打算、意欲做某事。</p></details><p><strong>表达迁移：</strong> 写一段口头自我纠正，先说明误说内容，再清楚给出正确安排。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I meant to say Thursday, but I accidentally said Tuesday. I corrected myself before anyone wrote it down. The meeting remained on Thursday.</p><p>第一句的组织方式：meant to say 表意图，said 是实际行为，but 标出意图与结果的不一致。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Thursday 与 Tuesday 不是同一天；不能只因都以 T 开头而在时间安排中混用。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-089">回看本课</a></p>',76)])])}const g=s(n,[["render",r]]);export{u as __pageData,g as default};
